// Rules that must give the same answer every time are checked in code, not by the LLM.
const body = $('Review webhook').first().json.body;
const facts = String(body.facts ?? '');
const draft = String(body.draft ?? '');
const squeeze = text => text.replace(/\s+/g, '');
const tokens = [...new Set(facts.match(/\d{1,2}월\s?\d{1,2}일|\d{1,2}:\d{2}/g) ?? [])];
const missing = tokens.filter(token => !squeeze(draft).includes(squeeze(token)));
const issues = [];
if (missing.length) issues.push({ code: 'missing_fact', detail: missing.join(', ') });
const personal = draft.match(/01[016789]-?\d{3,4}-?\d{4}|[\w.+-]+@[\w-]+\.[\w.]+/g) ?? [];
if (personal.length) issues.push({ code: 'personal_info', detail: personal.join(', ') });
if (draft.length > 600) issues.push({ code: 'too_long', detail: `${draft.length}자 (600자 이하)` });
return [{ json: { rule_issues: issues } }];

// The reviewer's contract: { passed, codes, issues }.
const raw = String($json.output ?? '').trim().replace(/^```(json)?\s*|```$/g, '');
let unsupported = [];
try { unsupported = JSON.parse(raw).unsupported ?? []; } catch (error) { unsupported = []; }
// Check the LLM's verdict too: a sentence whose words all appear in the facts is supported.
const facts = String($('Review webhook').first().json.body.facts ?? '');
const words = sentence => sentence.match(/[가-힣A-Za-z0-9]{2,}/g) ?? [];
unsupported = unsupported.map(String).filter(Boolean)
  .filter(sentence => words(sentence).some(word => !facts.includes(word)));
const issues = [...$('Rule checks').first().json.rule_issues];
if (unsupported.length) issues.push({ code: 'unsupported_claim', detail: unsupported.join(' / ') });
return [{ json: { passed: issues.length === 0, codes: issues.map(issue => issue.code), issues } }];
